		step(3088, 3255, 3, ObjectID.ROOFTOPS_DRAYNOR_WALLSCRAMBLE),
		step(3096, 3256, 3, ObjectID.ROOFTOPS_DRAYNOR_LEAPDOWN),
		step(3103, 3261, 0, ObjectID.ROOFTOPS_DRAYNOR_CRATE)),
	AL_KHARID(3265, 3163, 3318, 3195,
