/** Tracks the course the player is on, its obstacle objects and the player's progress round it. */
@RequiredArgsConstructor
class ObstacleTracker
{
	private final Client client;
	@Getter
	private final Set<TileObject> objects = new HashSet<>();
	@Getter
	private Course course;
	// Game ticks the player has stayed on the same tile.
	@Getter
	private int ticksStill;
	private CourseProgress progress;
	private WorldPoint lastTile;
	private int agilityXp = -1;

	int indexClicksAway(int clicks)
	{
		return progress.indexClicksAway(clicks);
	}

	boolean clickingFromElsewhere()
	{
		return progress.clickingFromElsewhere(lastTile);
	}

	/** Picks up obstacles already in the scene when the plugin is switched on; call on the client thread. */
	void scan()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (client.getGameState() != GameState.LOGGED_IN || worldView == null)
		{
			return;
		}
		for (Tile[][] plane : worldView.getScene().getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}
					for (GameObject gameObject : tile.getGameObjects())
					{
						track(gameObject);
					}
					track(tile.getWallObject());
					track(tile.getDecorativeObject());
					track(tile.getGroundObject());
				}
			}
		}
	}

	private void track(TileObject object)
	{
		if (object != null && Course.isObstacle(object.getId()))
		{
			objects.add(object);
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		track(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		track(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		track(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		track(event.getGroundObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objects.remove(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		objects.remove(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		objects.remove(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objects.remove(event.getGroundObject());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// A map load discards every object; they spawn again afterwards.
		if (event.getGameState() == GameState.LOADING)
		{
			objects.clear();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (progress != null)
		{
			progress.clicked(course.indexOf(event.getId()));
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.AGILITY)
		{
			return;
		}
		int before = agilityXp;
		agilityXp = event.getXp();
		if (progress != null && before >= 0 && agilityXp > before)
		{
			progress.xpDrop();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (progress != null && event.getActor() == client.getLocalPlayer())
		{
			progress.fell();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		WorldPoint at = player.getWorldLocation();
		ticksStill = at.equals(lastTile) ? ticksStill + 1 : 0;
		lastTile = at;

		Course near = Course.near(at);
		if (near != course)
		{
			course = near;
			progress = near == null ? null : start(near, at);
		}
		if (progress != null)
		{
			progress.tick(at);
		}
	}

	// A player first seen on a roof, as after logging in, is part-way round. On the ground the lap has yet to start,
	// which is how progress begins anyway.
	private CourseProgress start(Course on, WorldPoint at)
	{
		CourseProgress started = new CourseProgress(on.obstacles);
		WorldView worldView = client.getTopLevelWorldView();
		int completed = at.getPlane() == 0 ? -1 : on.lastCompletedAt(at, (from, to) ->
			WorldPoint.isInScene(worldView, to.getX(), to.getY())
				&& from.toWorldArea().canTravelInDirection(worldView, to.getX() - from.getX(), to.getY() - from.getY()));
		if (completed >= 0)
		{
			started.resumeAfter(completed);
		}
		return started;
	}
}

package com.rooftopobstaclepreview;

import com.google.common.primitives.Ints;
import net.runelite.api.coords.WorldPoint;

final class RooftopObstacle
{
	// Where the player stands when the obstacle's xp drops.
	final WorldPoint landing;
	private final int[] objectIds;

	RooftopObstacle(WorldPoint landing, int... objectIds)
	{
		this.landing = landing;
		this.objectIds = objectIds;
	}

	boolean is(int objectId)
	{
		return Ints.contains(objectIds, objectId);
	}

	/** The index of the obstacle that lands on the tile, or -1. */
	static int landingOn(RooftopObstacle[] obstacles, WorldPoint tile)
	{
		for (int index = 0; index < obstacles.length; index++)
		{
			if (obstacles[index].landing.equals(tile))
			{
				return index;
			}
		}
		return -1;
	}
}

package com.rooftopobstaclepreview;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Rooftop Obstacle Preview",
	description = "Shows where each rooftop obstacle's clickbox will be when it is your next click, coloured by click order",
	tags = {"agility", "rooftop", "clickbox", "overlay", "course"}
)
public class RooftopObstaclePreviewPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private EventBus eventBus;

	@Inject
	private OverlayManager overlayManager;

	private ObstacleTracker tracker;
	private GhostClickboxOverlay overlay;

	@Override
	protected void startUp()
	{
		tracker = new ObstacleTracker(client);
		overlay = new GhostClickboxOverlay(client, tracker);
		eventBus.register(tracker);
		clientThread.invoke(tracker::scan);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		eventBus.unregister(tracker);
	}
}

package com.rooftopobstaclepreview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class CourseProgressTest
{
	// Three obstacles: 0 lands on A, 1 on B and the last on C, where a lap starts.
	private static final WorldPoint A = new WorldPoint(10, 10, 3);
	private static final WorldPoint B = new WorldPoint(30, 20, 3);
	private static final WorldPoint C = new WorldPoint(40, 40, 0);

	private final CourseProgress progress = new CourseProgress(new RooftopObstacle[]{
		new RooftopObstacle(A, 1), new RooftopObstacle(B, 2), new RooftopObstacle(C, 3)});

	@Test
	public void lapStartsAtTheFirstObstacle()
	{
		progress.tick(C);
		assertEquals(0, next());
	}

	@Test
	public void setsOffOnLeavingAfterClickingNext()
	{
		progress.tick(C);
		progress.clicked(0);
		assertEquals(0, next());

		progress.tick(C.dx(1));
		assertEquals(1, next());
		assertEquals(0, progress.indexClicksAway(2));
	}

	@Test
	public void walkingOffWithoutClickingNextIsNotSettingOff()
	{
		progress.tick(C);
		assertFalse(progress.clickingFromElsewhere(C));

		progress.tick(C.dx(1));
		assertEquals(0, next());
		assertTrue(progress.clickingFromElsewhere(C.dx(1)));

		progress.clicked(0);
		progress.tick(C.dx(2));
		assertEquals(1, next());
		assertFalse(progress.clickingFromElsewhere(C.dx(2)));
	}

	@Test
	public void holdsThroughTheObstacleAndOnItsLandingTile()
	{
		progress.tick(C);
		progress.clicked(0);
		progress.tick(C.dx(1));
		progress.tick(new WorldPoint(12, 12, 1));
		assertEquals(1, next());

		land(A);
		progress.tick(A);
		assertEquals(1, next());

		progress.clicked(1);
		progress.tick(A.dy(1));
		assertEquals(2, next());
	}

	@Test
	public void landingTileIdentifiesTheObstacle()
	{
		progress.tick(C);
		land(B);
		assertEquals(2, next());
	}

	@Test
	public void unknownLandingTileFollowsLapOrder()
	{
		progress.tick(C);
		land(A.dx(1));
		assertEquals(1, next());
		assertTrue(progress.clickingFromElsewhere(A.dx(1)));
		assertFalse(progress.clickingFromElsewhere(A));
	}

	@Test
	public void clickOnAnotherObstacleOverridesLapOrder()
	{
		progress.tick(B);
		progress.clicked(2);
		land(C.dx(1));
		assertEquals(0, next());
	}

	@Test
	public void clickingAheadKeepsLapOrder()
	{
		progress.tick(C);
		progress.clicked(1);
		land(A.dx(1));
		assertEquals(1, next());
	}

	@Test
	public void reachingTheLandingTileATickLateIsNotLeaving()
	{
		progress.tick(C);
		land(A.dy(-1));
		progress.clicked(1);
		progress.tick(A);
		assertEquals(1, next());

		progress.tick(A.dy(1));
		assertEquals(2, next());
	}

	@Test
	public void lastObstacleWrapsToTheFirst()
	{
		progress.tick(B);
		land(C);
		assertEquals(0, next());

		progress.clicked(0);
		progress.tick(C.dx(1));
		assertEquals(1, next());
	}

	@Test
	public void fallRestartsTheLap()
	{
		progress.tick(C);
		land(A);
		progress.clicked(1);

		WorldPoint fallen = new WorldPoint(5, 5, 0);
		progress.fell();
		progress.tick(fallen);
		assertEquals(0, next());
		assertTrue(progress.clickingFromElsewhere(fallen));

		progress.tick(fallen.dx(1));
		assertEquals(0, next());

		progress.clicked(0);
		progress.tick(fallen.dx(2));
		assertEquals(1, next());
	}

	@Test
	public void resumesPartWayRound()
	{
		progress.resumeAfter(0);
		progress.tick(A.dy(4));
		assertEquals(1, next());
		assertTrue(progress.clickingFromElsewhere(A.dy(4)));

		progress.clicked(1);
		progress.tick(A.dy(5));
		assertEquals(2, next());
	}

	private int next()
	{
		return progress.indexClicksAway(0);
	}

	private void land(WorldPoint tile)
	{
		progress.xpDrop();
		progress.tick(tile);
	}
}

package com.rooftopobstaclepreview;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class CourseTest
{
	@Test
	public void findsTheCourseThePlayerIsOnOrBeside()
	{
		assertEquals(Course.ARDOUGNE, Course.near(new WorldPoint(2671, 3299, 3)));
		assertEquals(Course.DRAYNOR, Course.near(new WorldPoint(3103, 3279, 0)));
		assertEquals(Course.SEERS, Course.near(new WorldPoint(2729, 3489, 0)));
		// The bank south of Ardougne market.
		assertNull(Course.near(new WorldPoint(2655, 3283, 0)));
	}

	@Test
	public void coursesDoNotOverlap()
	{
		for (Course course : Course.values())
		{
			for (RooftopObstacle obstacle : course.obstacles)
			{
				assertEquals(course, Course.near(obstacle.landing));
			}
		}
	}

	@Test
	public void eitherFaladorLedgeIsTheSameStep()
	{
		assertEquals(10, Course.FALADOR.indexOf(ObjectID.ROOFTOPS_FALADOR_LEDGE_3A));
		assertEquals(10, Course.FALADOR.indexOf(ObjectID.ROOFTOPS_FALADOR_LEDGE_3B));
		assertEquals(13, Course.FALADOR.obstacles.length);
	}

	@Test
	public void playerOnARoofLastCompletedTheObstacleThatLandsOnIt()
	{
		// Ardougne's first roof, from its far end.
		assertEquals(0, Course.ARDOUGNE.lastCompletedAt(new WorldPoint(2672, 3309, 3),
			(from, to) -> to.getX() >= 2671 && to.getX() <= 2672 && to.getY() >= 3299 && to.getY() <= 3309));
		// No obstacle lands on this plane.
		assertEquals(-1, Course.ARDOUGNE.lastCompletedAt(new WorldPoint(2660, 3305, 1), (from, to) -> true));
	}
}

